export const guidanceStepDrafts = lessons.map(lesson => {
  const base = guidanceSourceDrafts.find(item => item.processKey === lesson.process)!.body;
  const body: GuidanceContentBody = {
    ...base, title: guidanceStepTitles[lesson.process][lesson.step], stepKey: lesson.step,
    audience: guidanceStepAudience(lesson.process, lesson.step),
    learningGoal: `${guidanceStepTitles[lesson.process][lesson.step]} adımında doğru veriyi ve işlem sonucunu kontrol etmek.`,
    prerequisites: lesson.prerequisites ?? "Doğru şirket, kişi ve işlem kaydını doğrulayın. İşlem için gerekli gerçek kaynağı ve yetkinizi kontrol edin.",
    action: lesson.action, why: lesson.why, example: lesson.example,
    counterExample: lesson.counterExample ?? lesson.choices.filter((_, index) => index !== lesson.correct).join("; "), correction: lesson.correction,
    terms: lesson.terms ?? base.terms, expertEscalation: lesson.expertEscalation ?? base.expertEscalation,
    outcome: lesson.outcome ?? "Bu alt adımın verisini ve etkisini kontrol ettik; eksik veya çelişkili bilgiyi uzmanla netleştirdik.",
    completionEvidence: lesson.completionEvidence ?? base.completionEvidence,
    nextStep: lesson.nextStep ?? "İlgili süreç ekranında sonraki adıma geçin; alıştırma yanıtını gerçek işlem kaydı saymayın.",
    sourceReference: lesson.source ?? base.sourceReference, provision: lesson.provision ?? base.provision,
    sourceKind: lesson.sourceKind ?? base.sourceKind,
    applicability: "Standart günlük işlemde öğretici kontrol. Kanuni hüküm ile Ekipzen ekran davranışı farklıdır; şirket koşulları ve istisnalar yayın öncesinde uzman tarafından incelenir.",
    practice: { question: lesson.question, choices: lesson.choices, correctChoice: lesson.correct, explanation: lesson.explanation },
  };
  return { contentKey: `${lesson.process}-${lesson.step}`, processKey: lesson.process, body };
});
